-- HzReyzn Hub | Halloween loading screen | 2026-10-13
-- Progress runs independently of image registration and preloading.
-- At 100%, a subtle flare repeats every 3 seconds; click/tap to continue.
-- Pega ESTE ARCHIVO COMPLETO antes del codigo de tu hub.
-- Al terminar la pantalla, la ejecucion continua debajo del bloque "do ... end".
-- Ejecutado solo, muestra la intro. No descarga ni ejecuta otro hub.
-- Imagenes y audio incluidos; requieren writefile + getcustomasset/getsynasset.
-- En Studio: usa un LocalScript y configura tus IDs de imagen y audio.
-- El progreso predeterminado mide la intro, no los recursos de todo el juego.

do
    local Config = {
        Duration = 6.5,                 -- no espera a las imagenes para avanzar
        Hold = 0.4,                     -- evita que un toque previo cierre la intro
        FadeOut = 1.2,
        WaitForInput = true,            -- tocar/clic/Enter/A al 100%
        AllowSkip = false,
        SkipAfter = 1.5,
        FlashInterval = 3,
        ReducedMotion = false,
        Quality = "Auto",              -- "Auto", "Low" o "High"
        AssetTimeout = 18,             -- solo limita la tarea de recursos
        PrepareTimeout = 30,
        AudioEnabled = true,
        AudioVolume = 0.48,             -- volumen local, no modifica el juego
        AudioFadeIn = 0.9,

        -- Opcional: reemplaza "" por "rbxassetid://TU_ID" en Roblox Studio.
        BackgroundImage = "",
        TitleImage = "",
        FogImage = "",
        AudioId = "",

        -- Opcional: function(reportProgress) ... end
        -- reportProgress recibe un numero entre 0 y 1.
        -- Si se usa Prepare, 100% solo se alcanza cuando esta funcion termina.
        -- Prepara aqui recursos; abre la GUI del hub despues de la intro.
        Prepare = nil,

        -- Opcional: function() ... end para abrir el hub al terminar.
        -- Usa OnReady O pega el hub al final del archivo; no ambas opciones.
        OnReady = nil,
    }

    local options = ...
    if type(options) == "table" then
        Config.Owner = options.Owner
        if options.ReducedMotion ~= nil then Config.ReducedMotion = options.ReducedMotion == true end
    end
    if Config.Owner and not Config.Owner.Parent then return "cancelled" end

    -- Las imagenes incrustadas se insertan automaticamente al empaquetar.
    local Embedded = {
        background = {fileName = "HzReyzn_Halloween_background_73f33b0ba613.png", byteLength = 2533303, data = [==[]==]},
        title = {fileName = "HzReyzn_Halloween_title_2f5b01417ec9.png", byteLength = 1586098, data = [==[]==]},
        fog = {fileName = "HzReyzn_Halloween_fog_bf33ac183d6c.png", byteLength = 1336064, data = [==[]==]},
        ambience = {fileName = "HzReyzn_Halloween_ambience_fe9f1379dfb5.ogg", byteLength = 875025, data = [==[]==]}
    }

    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local ContentProvider = game:GetService("ContentProvider")
    local TweenService = game:GetService("TweenService")
    local SoundService = game:GetService("SoundService")
    local player = Players.LocalPlayer
    if not player then
        warn("[HzReyzn] La pantalla se ejecuta en el cliente, no en el servidor.")
        return
    end
    local playerGui = player:WaitForChild("PlayerGui", 10)
    if not playerGui then
        warn("[HzReyzn] PlayerGui no esta disponible.")
        return
    end

    local parent = playerGui
    if type(gethui) == "function" then
        local ok, result = pcall(gethui)
        if ok and typeof(result) == "Instance" then parent = result end
    end
    local NAME = "HzReyznHalloweenLoading"
    -- Se usa una senal propia: no se borran otras interfaces ni efectos del juego.
    for _, previousName in ipairs({NAME, "HzReyznHalloween"}) do
        local previous = parent:FindFirstChild(previousName)
        if previous then
            local cancel = previous:FindFirstChild("CancelLoading")
            if cancel and cancel:IsA("BindableEvent") then cancel:Fire() end
            previous:Destroy()
        end
    end

    local state = {
        alive = true, cancelled = false, fade = 0, exitRequested = false,
        skipped = false, ready = false, prepared = Config.Prepare == nil,
        reported = 0, prepareError = nil, clock = 0,
    }
    local connections, threads, alphaEntries = {}, {}, {}
    local screen, ambience, audioStartedAt
    local function retireAudio()
        local sound = ambience
        ambience = nil
        if not sound then return end
        local volume = sound.Volume
        -- The usual close already follows the screen's fade. Also fade if an
        -- external script removes this screen, or the intro is run again.
        if sound.Parent and volume > 0.001 then
            task.spawn(function()
                local elapsed = 0
                while sound.Parent and elapsed < 0.35 do
                    local dt = task.wait(1 / 30)
                    elapsed = elapsed + (type(dt) == "number" and dt > 0 and dt or 1 / 30)
                    if sound.Parent then
                        local t = math.min(1, elapsed / 0.35)
                        sound.Volume = volume * (1 - t * t * (3 - 2 * t))
                    end
                end
                pcall(function() sound:Stop(); sound:Destroy() end)
            end)
        else
            pcall(function() sound:Stop(); sound:Destroy() end)
        end
    end
    local function disconnectAll()
        for _, connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections)
    end
    local function cleanup(cancelled)
        if not state.alive then return end
        state.alive = false
        state.cancelled = cancelled or false
        disconnectAll()
        retireAudio()
        for _, thread in ipairs(threads) do
            if coroutine.status(thread) ~= "dead" and thread ~= coroutine.running() then
                pcall(task.cancel, thread)
            end
        end
        if screen and screen.Parent then screen:Destroy() end
    end
    local function connect(signal, callback)
        local connection = signal:Connect(function(...)
            local ok, err = xpcall(callback, debug.traceback, ...)
            if not ok then
                warn("[HzReyzn] Error de animacion: " .. tostring(err))
                cleanup(false)
            end
        end)
        connections[#connections + 1] = connection
        return connection
    end
    local function spawn(callback)
        local thread = task.spawn(callback)
        threads[#threads + 1] = thread
        return thread
    end
    local function create(className, properties, container)
        local object = Instance.new(className)
        for key, value in pairs(properties or {}) do object[key] = value end
        object.Parent = container
        return object
    end
    local function alpha(object, property, base)
        local entry = {object = object, property = property, base = base}
        alphaEntries[#alphaEntries + 1] = entry
        object[property] = 1 - (1 - base) * state.fade
        return entry
    end
    local function setAlpha(entry, base)
        entry.base = math.clamp(base, 0, 1)
        entry.object[entry.property] = 1 - (1 - entry.base) * state.fade
    end
    local function updateAudio()
        if not ambience or not ambience.Parent then return end
        if ambience.IsLoaded and not audioStartedAt then audioStartedAt = state.clock end
        local t = audioStartedAt and math.clamp((state.clock - audioStartedAt)
            / math.max(0.1, tonumber(Config.AudioFadeIn) or 0.9), 0, 1) or 0
        local envelope = t * t * (3 - 2 * t)
        ambience.Volume = math.clamp(tonumber(Config.AudioVolume) or 0.48, 0, 1) * envelope * state.fade
    end
    local function setFade(value)
        value = math.clamp(value, 0, 1)
        if state.fade == value then updateAudio(); return end
        state.fade = value
        for _, entry in ipairs(alphaEntries) do
            entry.object[entry.property] = 1 - (1 - entry.base) * value
        end
        updateAudio()
    end
    local function frame(container, properties, base)
        properties.BorderSizePixel = 0
        local object = create("Frame", properties, container)
        if base ~= nil then alpha(object, "BackgroundTransparency", base) end
        return object
    end
    local function image(container, properties, base)
        properties.BackgroundTransparency = 1
        properties.BorderSizePixel = 0
        local object = create("ImageLabel", properties, container)
        local entry = alpha(object, "ImageTransparency", base or 0)
        return object, entry
    end
    local function textLabel(container, properties, base)
        properties.BackgroundTransparency = 1
        properties.BorderSizePixel = 0
        local object = create("TextLabel", properties, container)
        local entry = alpha(object, "TextTransparency", base or 0)
        return object, entry
    end
    local function corner(object, radius)
        create("UICorner", {CornerRadius = UDim.new(0, radius)}, object)
    end
    local function outline(object, color, thickness, transparency)
        local stroke = create("UIStroke", {Color = color, Thickness = thickness}, object)
        alpha(stroke, "Transparency", transparency or 0)
        return stroke
    end
    local function nseq(points)
        local keys = {}
        for _, point in ipairs(points) do
            keys[#keys + 1] = NumberSequenceKeypoint.new(point[1], point[2])
        end
        return NumberSequence.new(keys)
    end
    local function cseq(points)
        local keys = {}
        for _, point in ipairs(points) do
            keys[#keys + 1] = ColorSequenceKeypoint.new(point[1], point[2])
        end
        return ColorSequence.new(keys)
    end
    local RGB, U2, V2 = Color3.fromRGB, UDim2.fromScale, Vector2.new
    local ORANGE, IVORY, VIOLET = RGB(255, 117, 28), RGB(255, 221, 156), RGB(174, 76, 255)
    local mobile = UserInputService.TouchEnabled
    local low = Config.Quality == "Low" or (Config.Quality == "Auto" and mobile)
    local reduced = Config.ReducedMotion
    local duration = math.max(1, tonumber(Config.Duration) or 6.5)
    local fadeOut = math.max(0.15, tonumber(Config.FadeOut) or 0.85)

    -- Decodificador incremental: cede el hilo para mantener la UI fluida.
    local function decodeBase64(data)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local values = {}
        for i = 1, #alphabet do values[string.byte(alphabet, i)] = i - 1 end
        values[61] = 0
        local parts, blocks = {}, {}
        local length = #data
        for i = 1, length, 4 do
            if not state.alive then return nil end
            local a, b, c, d = string.byte(data, i, i + 3)
            if not (values[a] and values[b] and values[c] and values[d]) then
                error("Datos de recurso invalidos")
            end
            local n = values[a] * 262144 + values[b] * 4096 + values[c] * 64 + values[d]
            local x = math.floor(n / 65536) % 256
            local y = math.floor(n / 256) % 256
            local z = n % 256
            parts[#parts + 1] = c == 61 and string.char(x)
                or (d == 61 and string.char(x, y) or string.char(x, y, z))
            if #parts >= 16384 then
                blocks[#blocks + 1] = table.concat(parts)
                table.clear(parts)
                task.wait()
            end
        end
        if #parts > 0 then blocks[#blocks + 1] = table.concat(parts) end
        return table.concat(blocks)
    end
    local function resolveAsset(key, configured)
        if type(configured) == "string" and configured ~= "" then return configured end
        local asset = Embedded[key]
        local register = getcustomasset or getsynasset
        if not asset or type(register) ~= "function" or type(writefile) ~= "function" then
            return ""
        end
        local path = asset.fileName
        local exists = false
        if type(isfile) == "function" then
            local ok, result = pcall(isfile, path)
            exists = ok and result == true
        end
        if exists and type(readfile) == "function" then
            local ok, bytes = pcall(readfile, path)
            local signature = key == "ambience" and "OggS" or "\137PNG\13\10\26\10"
            exists = ok and type(bytes) == "string" and #bytes == asset.byteLength
                and bytes:sub(1, #signature) == signature
        end
        if not exists then
            local bytes = decodeBase64(asset.data)
            if not bytes or not state.alive then return "" end
            assert(#bytes == asset.byteLength, "Recurso incompleto")
            writefile(path, bytes)
        end
        if not state.alive then return "" end
        local uri = register(path)
        return type(uri) == "string" and uri or ""
    end

    local function run()
        screen = create("ScreenGui", {
            Name = NAME, ResetOnSpawn = false, IgnoreGuiInset = true,
            DisplayOrder = 100000, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        }, parent)
        pcall(function() screen.ScreenInsets = Enum.ScreenInsets.None end)
        local cancel = create("BindableEvent", {Name = "CancelLoading"}, screen)
        connect(cancel.Event, function() cleanup(true) end)
        connect(screen.Destroying, function() cleanup(true) end)
        if Config.Owner then
            connect(Config.Owner.Destroying, function() cleanup(true) end)
            if not Config.Owner.Parent then cleanup(true); return "cancelled" end
        end
        -- Heartbeat's elapsed seconds also work when os.clock is replaced by an executor.
        connect(RunService.Heartbeat, function(dt)
            if type(dt) == "number" and dt == dt and dt > 0 and dt < math.huge then
                state.clock = state.clock + dt
            end
        end)

        local input = create("TextButton", {
            Name = "InputShield", Size = U2(1, 1), Text = "", AutoButtonColor = false,
            BorderSizePixel = 0, BackgroundColor3 = RGB(5, 4, 7),
            Active = true, Modal = true, ZIndex = 1,
        }, screen)
        alpha(input, "BackgroundTransparency", 0)
        create("UIGradient", {Rotation = 30, Color = cseq({
            {0, RGB(17, 5, 35)}, {0.48, RGB(8, 6, 14)}, {1, RGB(46, 13, 7)},
        })}, input)
        local root = frame(input, {
            Name = "Scene", Size = U2(1, 1), BackgroundTransparency = 1,
            ClipsDescendants = true, ZIndex = 2,
        })
        local background, backgroundAlpha = image(root, {
            Name = "Background", AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0.5),
            Size = U2(1.025, 1.025), ScaleType = Enum.ScaleType.Crop, ZIndex = 1,
        })
        local colorWash = frame(root, {
            Name = "HalloweenColor", Size = U2(1, 1), BackgroundColor3 = RGB(255, 255, 255), ZIndex = 2,
        }, 0.85)
        local washGradient = create("UIGradient", {Rotation = 24, Color = cseq({
            {0, RGB(113, 26, 228)}, {0.36, RGB(80, 26, 115)}, {0.62, RGB(133, 27, 73)},
            {1, RGB(255, 81, 5)},
        }), Transparency = nseq({{0, 0.16}, {0.43, 0.76}, {0.57, 0.88}, {1, 0.12}})}, colorWash)
        local veil = frame(root, {
            Name = "CentralShadow", Size = U2(1, 1), BackgroundColor3 = RGB(2, 3, 7), ZIndex = 2,
        }, 0.6)
        create("UIGradient", {
            Rotation = 90, Transparency = nseq({{0, 1}, {0.25, 0.6}, {0.5, 0.05}, {0.75, 0.8}, {1, 1}}),
        }, veil)

        local fogs, imageTargets = {}, {background}
        for i = 1, (low and 3 or 5) do
            local fog, fogAlpha = image(root, {
                Name = "Mist" .. i, AnchorPoint = V2(0.5, 0.5),
                Position = U2(0.5, 0.42 + i * 0.105), Size = U2(1.15, 0.22 + i * 0.025),
            ImageColor3 = i % 2 == 0 and RGB(183, 122, 230) or RGB(206, 151, 132),
                ZIndex = i > 2 and 4 or 2,
            }, 0.79 + i * 0.018)
            fogs[#fogs + 1] = {object = fog, alpha = fogAlpha, index = i}
            imageTargets[#imageTargets + 1] = fog
        end
        local candleGlows = {}
        for _, x in ipairs({0.12, 0.88}) do
            local glow, glowAlpha = image(root, {
                Name = "PumpkinLight", AnchorPoint = V2(0.5, 0.5), Position = U2(x, 0.77),
                Size = U2(0.29, 0.38), ImageColor3 = RGB(255, 82, 7), ZIndex = 3,
            }, 0.76)
            candleGlows[#candleGlows + 1] = {object = glow, alpha = glowAlpha, phase = x * 9}
            imageTargets[#imageTargets + 1] = glow
        end

        local stage = frame(root, {
            Name = "Content", AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0.5),
            Size = UDim2.fromOffset(1600, 900), BackgroundTransparency = 1, ZIndex = 5,
        })
        local stageScale = create("UIScale", {Scale = 1}, stage)
        local function layout()
            local size = root.AbsoluteSize
            stageScale.Scale = math.max(0.1, math.min(size.X / 1600, size.Y / 900))
        end
        layout()
        connect(root:GetPropertyChangedSignal("AbsoluteSize"), layout)

        local particles = {}
        local random = Random.new(1031)
        local count = reduced and 0 or (low and 24 or 44)
        for i = 1, count do
            local size = random:NextNumber(1.2, i % 7 == 0 and 6.2 or 3.3)
            local p = frame(stage, {
                Name = "Ember", AnchorPoint = V2(0.5, 0.5), Size = UDim2.fromOffset(size, size * 1.8),
                BackgroundColor3 = i % 7 == 0 and VIOLET or (i % 4 == 0 and IVORY or ORANGE), Rotation = 18, ZIndex = 2,
            })
            local a = alpha(p, "BackgroundTransparency", 1)
            corner(p, 3)
            create("UIGradient", {Rotation = 90,
                Transparency = nseq({{0, 1}, {0.25, 0.2}, {0.5, 0}, {0.75, 0.35}, {1, 1}})}, p)
            particles[#particles + 1] = {
                object = p, alpha = a, x = random:NextNumber(90, 1510),
                offset = random:NextNumber(0, 1), life = random:NextNumber(8, 16),
                drift = random:NextNumber(-70, 70), sway = random:NextNumber(10, 28),
                opacity = i % 7 == 0 and 0.28 or 0.66,
            }
        end

        local logoHost = frame(stage, {
            Name = "Title", AnchorPoint = V2(0.5, 0.5),
            Position = UDim2.fromOffset(800, 344), Size = UDim2.fromOffset(1140, 300),
            BackgroundTransparency = 1, ZIndex = 6,
        })
        local logoScale = create("UIScale", {Scale = 0.96}, logoHost)
        -- Native gothic typography remains colored and detailed if a local PNG is unavailable.
        local nativeTitle = frame(logoHost, {
            Name = "NativeTitle", Size = U2(1, 1), BackgroundTransparency = 1, ZIndex = 1,
        })
        local nativeLayers = {}
        local function lettering(name, color, offsetX, offsetY, z, transparency)
            local label, a = textLabel(nativeTitle, {
                Name = name, Size = U2(1, 1), Position = UDim2.fromOffset(offsetX, offsetY),
                Text = "HzReyzn Hub", Font = Enum.Font.GrenzeGotisch,
                TextColor3 = color, TextSize = 150, TextScaled = true, ZIndex = z,
            }, transparency)
            pcall(function() label.FontFace = Font.new("rbxasset://fonts/families/GrenzeGotisch.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal) end)
            create("UITextSizeConstraint", {MaxTextSize = 160, MinTextSize = 72}, label)
            nativeLayers[#nativeLayers + 1] = {label = label, alpha = a, base = transparency or 0}
            return label, a
        end
        local depth = lettering("DeepShadow", RGB(9, 3, 13), 0, 10, 1, 0.03)
        outline(depth, RGB(4, 2, 6), 5, 0.2)
        lettering("MetalDepth", RGB(91, 25, 39), 0, 5, 2, 0)
        local bevel = lettering("CopperBevel", RGB(232, 78, 19), 0, 2, 3, 0)
        outline(bevel, RGB(153, 51, 119), 2.4, 0.17)
        local fallback = lettering("GothicFace", RGB(255, 255, 255), 0, 0, 4, 0)
        local nativeGradient = create("UIGradient", {Rotation = 90, Color = cseq({
            {0, RGB(255, 199, 92)}, {0.22, RGB(255, 237, 181)}, {0.44, RGB(255, 153, 42)},
            {0.53, RGB(161, 47, 22)}, {0.59, RGB(255, 187, 70)}, {0.82, RGB(235, 83, 78)},
            {1, RGB(178, 56, 172)},
        })}, fallback)
        outline(fallback, RGB(73, 23, 40), 1.2, 0.18)
        local nativeShine = lettering("LetterReflection", RGB(255, 241, 207), 0, 0, 5, 0.54)
        local nativeShineGradient = create("UIGradient", {Rotation = 16,
            Transparency = nseq({{0, 1}, {0.44, 1}, {0.5, 0}, {0.56, 1}, {1, 1}}),
        }, nativeShine)
        local shadow = image(logoHost, {
            Name = "TitleShadow", Size = U2(1, 1), Position = UDim2.fromOffset(0, 9),
            ImageColor3 = RGB(0, 0, 0), ScaleType = Enum.ScaleType.Fit, ZIndex = 1,
        }, 0.23)
        local logo, logoAlpha = image(logoHost, {
            Name = "TitleArtwork", Size = U2(1, 1), ScaleType = Enum.ScaleType.Fit, ZIndex = 2,
            ImageColor3 = RGB(255, 203, 140),
        }, 0)
        create("UIGradient", {Rotation = 82, Color = cseq({
            {0, RGB(255, 231, 201)}, {0.42, RGB(255, 196, 107)},
            {0.62, RGB(255, 162, 102)}, {1, RGB(234, 113, 198)},
        })}, logo)
        local shine, shineAlpha = image(logoHost, {
            Name = "TitleShine", Size = U2(1, 1), ImageColor3 = RGB(255, 235, 194),
            ScaleType = Enum.ScaleType.Fit, ZIndex = 4,
        }, 1)
        local shineGradient = create("UIGradient", {
            Rotation = 15, Offset = V2(-1, 0),
            Transparency = nseq({{0, 1}, {0.42, 1}, {0.5, 0.1}, {0.58, 1}, {1, 1}}),
        }, shine)
        imageTargets[#imageTargets + 1] = logo
        imageTargets[#imageTargets + 1] = shadow
        imageTargets[#imageTargets + 1] = shine

        -- A slim obsidian rail with a warm inner core; the percentage is plain text.
        local barDetails = {}
        local bar = frame(stage, {
            Name = "LoadingBar", AnchorPoint = V2(0.5, 0.5),
            Position = UDim2.fromOffset(800, 529), Size = UDim2.fromOffset(880, 16),
            BackgroundColor3 = RGB(7, 5, 12), ZIndex = 8,
        }, 0.08)
        corner(bar, 8)
        local barStroke = outline(bar, RGB(255, 255, 255), 1, 0.4)
        barDetails.metal = create("UIGradient", {Color = cseq({
            {0, RGB(145, 61, 194)}, {0.45, RGB(153, 65, 38)}, {1, RGB(255, 167, 84)},
        })}, barStroke)
        local underglow = frame(stage, {
            Name = "BarUnderglow", AnchorPoint = V2(0.5, 0.5),
            Position = UDim2.fromOffset(800, 536), Size = UDim2.fromOffset(868, 32),
            BackgroundColor3 = ORANGE, ZIndex = 7,
        })
        corner(underglow, 16)
        barDetails.underglowAlpha = alpha(underglow, "BackgroundTransparency", 0.9)
        create("UIGradient", {Rotation = 90,
            Transparency = nseq({{0, 1}, {0.32, 0.4}, {0.5, 0.05}, {1, 1}})}, underglow)
        local clip = frame(bar, {
            Name = "Trough", Position = UDim2.fromOffset(3, 3), Size = UDim2.new(1, -6, 1, -6),
            BackgroundColor3 = RGB(3, 2, 6), ClipsDescendants = true, ZIndex = 2,
        }, 0)
        corner(clip, 5)
        local fill = frame(clip, {
            Name = "Progress", Size = U2(0, 1), BackgroundColor3 = RGB(255, 255, 255),
            ClipsDescendants = true, ZIndex = 3,
        }, 0)
        corner(fill, 5)
        local fireGradient = create("UIGradient", {Color = cseq({
            {0, RGB(99, 42, 156)}, {0.3, RGB(193, 58, 32)},
            {0.7, RGB(255, 120, 24)}, {1, RGB(255, 211, 139)},
        })}, fill)
        local fireTexture = image(fill, {
            Name = "InnerFlow", AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0.5),
            Size = U2(1.65, 4), ImageColor3 = RGB(255, 211, 140), ZIndex = 4,
        }, 0.82)
        imageTargets[#imageTargets + 1] = fireTexture
        barDetails.sheen = frame(fill, {
            Name = "LightSweep", Size = U2(1, 1), BackgroundColor3 = IVORY, ZIndex = 8,
        }, 0.55)
        barDetails.sheenGradient = create("UIGradient", {Rotation = 18,
            Transparency = nseq({{0, 1}, {0.38, 1}, {0.5, 0.05}, {0.62, 1}, {1, 1}})}, barDetails.sheen)
        local topLight = frame(fill, {
            Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = IVORY, ZIndex = 5,
        }, 0.3)
        local head = frame(clip, {
            Name = "LeadingLight", AnchorPoint = V2(0.5, 0), Size = UDim2.new(0, 2, 1, 0),
            BackgroundColor3 = RGB(255, 244, 212), ZIndex = 6,
        }, 0.08)
        local halo = frame(clip, {
            Name = "LeadingGlow", AnchorPoint = V2(0.5, 0), Size = UDim2.new(0, 48, 1, 0),
            BackgroundColor3 = IVORY, ZIndex = 5,
        }, 0.35)
        create("UIGradient", {Transparency = nseq({{0, 1}, {0.5, 0}, {1, 1}})}, halo)
        local barReflection = frame(clip, {
            Name = "CompletionReflection", Size = U2(1, 1), BackgroundColor3 = IVORY, ZIndex = 9,
        })
        local reflectionAlpha = alpha(barReflection, "BackgroundTransparency", 1)
        local reflectionGradient = create("UIGradient", {Rotation = 18,
            Transparency = nseq({{0, 1}, {0.42, 1}, {0.5, 0}, {0.58, 1}, {1, 1}})}, barReflection)
        local percent = textLabel(stage, {
            Name = "Percentage", AnchorPoint = V2(1, 1), Position = UDim2.fromOffset(1240, 509),
            Size = UDim2.fromOffset(110, 34), Text = "0%", Font = Enum.Font.GothamMedium,
            TextSize = 26, TextColor3 = IVORY, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 10,
        })
        local caption = textLabel(stage, {
            Name = "Status", AnchorPoint = V2(0.5, 0), Position = UDim2.fromOffset(800, 563),
            Size = UDim2.fromOffset(620, 45), Text = "Loading Hub", Font = Enum.Font.GrenzeGotisch,
            TextSize = 31, TextColor3 = RGB(255, 206, 135), ZIndex = 9,
        })
        outline(caption, RGB(38, 10, 30), 1, 0.2)
        for _, x in ipairs({510, 1020}) do
            local line = frame(stage, {
                Position = UDim2.fromOffset(x, 586), Size = UDim2.fromOffset(70, 1),
                BackgroundColor3 = RGB(169, 127, 79), ZIndex = 8,
            }, 0.4)
            create("UIGradient", {Transparency = nseq({{0, 1}, {0.5, 0}, {1, 1}})}, line)
        end
        local hint, hintAlpha = textLabel(stage, {
            Name = "ContinueHint", AnchorPoint = V2(0.5, 0), Position = UDim2.fromOffset(800, 619),
            Size = UDim2.fromOffset(900, 35), Text = "", Font = Enum.Font.Gotham,
            TextSize = 17, TextColor3 = RGB(227, 179, 217), ZIndex = 9,
        }, 0.15)
        local sparks = {}
        for i = 1, (reduced and 0 or (low and 3 or 5)) do
            local spark = frame(stage, {
                Name = "BarEmber", Size = UDim2.fromOffset(1.8, 4), BackgroundColor3 = i % 3 == 0 and IVORY or ORANGE,
                AnchorPoint = V2(0.5, 0.5), Rotation = 18, ZIndex = 10,
            })
            corner(spark, 2)
            create("UIGradient", {Rotation = 90, Transparency = nseq({{0, 1}, {0.5, 0}, {1, 1}})}, spark)
            sparks[#sparks + 1] = {object = spark, alpha = alpha(spark, "BackgroundTransparency", 1),
                offset = i / 10, speed = random:NextNumber(0.9, 1.6), drift = random:NextNumber(8, 40)}
        end

        local rims, optics = {}, {reflections = {}}
        for i, data in ipairs({
            {UDim2.new(0, 22, 0, 18), UDim2.new(1, -44, 0, 1), 0},
            {UDim2.new(0, 22, 1, -19), UDim2.new(1, -44, 0, 1), 0},
            {UDim2.new(0, 20, 0, 22), UDim2.new(0, 1, 1, -44), 90},
            {UDim2.new(1, -21, 0, 22), UDim2.new(0, 1, 1, -44), 90},
        }) do
            local horizontal = data[3] == 0
            local pos, size = data[1], data[2]
            local black = frame(root, {
                Name = "ObsidianRim", Position = UDim2.new(pos.X.Scale, pos.X.Offset - (horizontal and 0 or 9),
                    pos.Y.Scale, pos.Y.Offset - (horizontal and 9 or 0)),
                Size = UDim2.new(size.X.Scale, size.X.Offset + (horizontal and 0 or 18),
                    size.Y.Scale, size.Y.Offset + (horizontal and 18 or 0)),
                BackgroundColor3 = RGB(0, 0, 0), ZIndex = 9,
            }, 0.22)
            create("UIGradient", {Rotation = horizontal and 90 or 0,
                Transparency = nseq({{0, 1}, {0.32, 0.2}, {0.5, 0}, {0.68, 0.2}, {1, 1}})}, black)
            for layer = 1, 2 do
                local width = layer == 1 and 7 or 3
                local glow = frame(root, {
                    Name = "NeonHalo", Position = UDim2.new(pos.X.Scale, pos.X.Offset - (horizontal and 0 or width / 2),
                        pos.Y.Scale, pos.Y.Offset - (horizontal and width / 2 or 0)),
                    Size = UDim2.new(size.X.Scale, size.X.Offset + (horizontal and 0 or width),
                        size.Y.Scale, size.Y.Offset + (horizontal and width or 0)),
                    BackgroundColor3 = RGB(255, 255, 255), ZIndex = 10,
                }, layer == 1 and 0.94 or 0.82)
                create("UIGradient", {Rotation = data[3], Color = cseq({
                    {0, RGB(148, 39, 237)}, {0.5, RGB(241, 77, 39)}, {1, RGB(255, 148, 36)},
                }), Transparency = nseq({{0, 0.6}, {0.18, 0.05}, {0.5, 0.38}, {0.82, 0.05}, {1, 0.6}})}, glow)
            end
            local rim = frame(root, {Name = "NeonCore", Position = data[1], Size = data[2],
                BackgroundColor3 = RGB(255, 255, 255), ZIndex = 11}, 0.14)
            local gradient = create("UIGradient", {Rotation = data[3],
                Color = cseq({{0, RGB(255, 164, 78)}, {0.46, RGB(224, 90, 150)}, {1, RGB(187, 102, 255)}}),
                Transparency = nseq({{0, 0.94}, {0.24, 0.73}, {0.5, 0.08}, {0.76, 0.73}, {1, 0.94}})}, rim)
            rims[#rims + 1] = gradient
        end
        for i = 1, 2 do
            local pane = frame(root, {
                Name = "LensReflection", Size = U2(1, 1), BackgroundColor3 = i == 1 and RGB(195, 155, 255) or RGB(255, 204, 153),
                ZIndex = 6,
            }, i == 1 and 0.974 or 0.986)
            local gradient = create("UIGradient", {Rotation = i == 1 and 24 or -28,
                Transparency = nseq({{0, 1}, {0.39, 1}, {0.48, 0.35}, {0.5, 0}, {0.52, 0.7}, {0.63, 1}, {1, 1}})}, pane)
            optics.reflections[#optics.reflections + 1] = gradient
        end

        -- Four broad inward fades stay behind the title and controls.
        optics.inward = {}
        for _, edge in ipairs({
            {U2(0, 0), U2(0.13, 1), 0, VIOLET},
            {U2(0.87, 0), U2(0.13, 1), 180, ORANGE},
            {U2(0, 0), U2(1, 0.17), 90, VIOLET},
            {U2(0, 0.83), U2(1, 0.17), 270, ORANGE},
        }) do
            local glow = frame(root, {Name = "InwardNeon", Position = edge[1], Size = edge[2],
                BackgroundColor3 = edge[4], ZIndex = 3})
            local opacity = alpha(glow, "BackgroundTransparency", 0.83)
            create("UIGradient", {Rotation = edge[3],
                Transparency = nseq({{0, 0.05}, {0.15, 0.3}, {0.45, 0.78}, {1, 1}})}, glow)
            optics.inward[#optics.inward + 1] = opacity
        end

        -- One pooled flare; nothing is spawned repeatedly after completion.
        local flareHost = frame(stage, {
            Name = "CompletionFlare", AnchorPoint = V2(0.5, 0.5),
            Position = UDim2.fromOffset(1237, 529), Size = UDim2.fromOffset(100, 100),
            BackgroundTransparency = 1, ZIndex = 14,
        })
        local flareScale = create("UIScale", {Scale = 0.8}, flareHost)
        local flareEntries = {}
        for i, rotation in ipairs({0, 90, 45, -45}) do
            local ray = frame(flareHost, {
                AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0.5),
                Size = UDim2.fromOffset(i < 3 and 86 or 47, i < 3 and 3 or 2),
                Rotation = rotation, BackgroundColor3 = i < 3 and IVORY or RGB(225, 150, 248),
                ZIndex = 2,
            })
            flareEntries[#flareEntries + 1] = alpha(ray, "BackgroundTransparency", 1)
            create("UIGradient", {Transparency = nseq({{0, 1}, {0.43, 0.3}, {0.5, 0}, {0.57, 0.3}, {1, 1}})}, ray)
        end
        local flareRing = frame(flareHost, {
            Name = "FlareRing", AnchorPoint = V2(0.5, 0.5), Position = U2(0.5, 0.5),
            Size = UDim2.fromOffset(36, 36), BackgroundTransparency = 1, ZIndex = 1,
        })
        corner(flareRing, 99)
        local flareRingStroke = create("UIStroke", {Color = RGB(255, 190, 103), Thickness = 1}, flareRing)
        local flareRingAlpha = alpha(flareRingStroke, "Transparency", 1)
        local flashVeil = frame(root, {
            Name = "CompletionFlash", Size = U2(1, 1), BackgroundColor3 = RGB(255, 199, 141), ZIndex = 16,
        })
        local flashAlpha = alpha(flashVeil, "BackgroundTransparency", 1)

        local skip = create("TextButton", {
            Name = "Skip", AnchorPoint = V2(1, 0), Position = UDim2.new(1, -30, 0, 28),
            Size = UDim2.fromOffset(94, 34), Text = "Skip", TextSize = 14,
            Font = Enum.Font.GothamMedium, TextColor3 = IVORY,
            BackgroundColor3 = RGB(18, 11, 8), BorderSizePixel = 0, AutoButtonColor = false,
            Visible = false, ZIndex = 20,
        }, root)
        corner(skip, 7)
        outline(skip, RGB(157, 96, 40), 1, 0.38)
        alpha(skip, "BackgroundTransparency", 0.32)
        alpha(skip, "TextTransparency", 0.05)

        local completeTime, exitTime, titleSeenAt
        local current, lastPercent = 0, -1
        local assigned, assetWorkers, assetFinished = {}, {}, 0
        local preloadThread

        -- Registration runs cooperatively, independently for each resource.
        -- PreloadAsync is advisory: it NEVER controls the progress bar.
        local specs = {
            {"background", Config.BackgroundImage, function(uri) background.Image = uri end},
            {"title", Config.TitleImage, function(uri)
                logo.Image, shadow.Image, shine.Image = uri, uri, uri
            end},
            {"fog", Config.FogImage, function(uri)
                for _, fog in ipairs(fogs) do fog.object.Image = uri end
                for _, glow in ipairs(candleGlows) do glow.object.Image = uri end
                fireTexture.Image = uri
            end},
        }
        if Config.AudioEnabled then
            table.insert(specs, 1, {"ambience", Config.AudioId, function(uri)
                ambience = create("Sound", {
                    Name = "HzReyznHalloweenAmbience", SoundId = uri,
                    Volume = 0, Looped = true, PlaybackSpeed = 1, PlayOnRemove = false,
                }, SoundService)
                -- Play queues playback while loading; no Loaded:Wait() can
                -- hold the bar, the click handler, or the closing animation.
                ambience:Play()
            end})
        end
        for _, spec in ipairs(specs) do
            local worker = spawn(function()
                local ok, err = xpcall(function()
                    local uri = resolveAsset(spec[1], spec[2])
                    if state.alive and uri ~= "" then
                        spec[3](uri)
                        assigned[spec[1]] = state.clock
                    end
                end, debug.traceback)
                if not state.alive then return end
                if not ok then warn("[HzReyzn] No se pudo preparar " .. spec[1] .. ": " .. tostring(err)) end
                assetFinished = assetFinished + 1
            end)
            assetWorkers[#assetWorkers + 1] = worker
        end
        preloadThread = spawn(function()
            while state.alive and assetFinished < #specs do task.wait(0.1) end
            if not state.alive then return end
            local list = {}
            for _, object in ipairs({background, logo, fireTexture}) do
                if object.Image ~= "" then list[#list + 1] = object end
            end
            if #list > 0 then pcall(function() ContentProvider:PreloadAsync(list) end) end
        end)

        local prepareThread
        if type(Config.Prepare) == "function" then
            prepareThread = spawn(function()
                local ok, err = xpcall(function()
                    Config.Prepare(function(value)
                        if not state.alive or type(value) ~= "number" or value ~= value then return end
                        state.reported = math.max(state.reported, math.clamp(value, 0, 1))
                    end)
                end, debug.traceback)
                if not state.alive then return end
                if not ok then state.prepareError = tostring(err) end
                state.prepared = true
            end)
        end

        local function requestContinue()
            if state.ready and completeTime and state.clock - completeTime >= math.max(0.25, Config.Hold) then
                state.exitRequested = true
            end
        end
        local function requestSkip()
            if state.ready then requestContinue(); return end
            if Config.AllowSkip and state.clock >= Config.SkipAfter and state.prepared then
                state.skipped = true
            end
        end
        connect(skip.Activated, requestSkip)
        connect(input.Activated, requestContinue)
        connect(UserInputService.InputEnded, function(event)
            if event.UserInputType == Enum.UserInputType.Touch or event.UserInputType == Enum.UserInputType.MouseButton1 then
                requestContinue()
            end
        end)
        connect(UserInputService.InputBegan, function(event, consumed)
            if consumed then return end
            if event.KeyCode == Enum.KeyCode.Return or event.KeyCode == Enum.KeyCode.ButtonA then
                requestContinue()
            elseif event.KeyCode == Enum.KeyCode.Escape then requestSkip() end
        end)

        local function smooth(x)
            x = math.clamp(x, 0, 1)
            return x * x * (3 - 2 * x)
        end
        local assetDeadlineHandled = false
        connect(RunService.RenderStepped, function(dt)
            if not state.alive then return end
            local elapsed = state.clock
            if not assetDeadlineHandled and elapsed >= Config.AssetTimeout then
                assetDeadlineHandled = true
                for _, worker in ipairs(assetWorkers) do
                    if coroutine.status(worker) ~= "dead" then pcall(task.cancel, worker) end
                end
                if preloadThread and coroutine.status(preloadThread) ~= "dead" then
                    pcall(task.cancel, preloadThread)
                end
            end
            if not state.prepared and elapsed >= Config.PrepareTimeout then
                if prepareThread then pcall(task.cancel, prepareThread) end
                state.prepareError = "La preparacion del hub excedio el tiempo limite."
                state.prepared = true
            end

            -- Exact finite timeline: no asymptote at 9%, 99% or 100%.
            local desired = smooth(elapsed / duration)
            if state.skipped then desired = 1 end
            if state.prepareError then
                desired = current
            elseif Config.Prepare ~= nil and not state.prepared then
                desired = math.min(desired, math.max(0.02, state.reported * 0.95))
            end
            current = math.max(current, desired)
            if elapsed >= duration and state.prepared and not state.prepareError then current = 1 end

            local entry = TweenService:GetValue(math.clamp(elapsed / 1.2, 0, 1), Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
            local bob = reduced and 0 or math.sin(elapsed * 0.65) * 4.5
            logoHost.Position = UDim2.fromOffset(800 + (reduced and 0 or math.sin(elapsed * 0.37) * 2.8),
                344 - (reduced and 0 or (1 - entry) * 38) + bob)
            logoHost.Rotation = reduced and 0 or math.sin(elapsed * 0.31) * 0.12
            logoScale.Scale = reduced and 1 or (0.975 + 0.025 * entry + math.sin(elapsed * 0.46) * 0.0018 * entry)

            -- Let the actual image render while it is loading. Hiding it until
            -- IsLoaded was true could leave the client showing the plain fallback.
            local hasLogo = logo.Image ~= ""
            local artworkLoaded = hasLogo and logo.IsLoaded
            if artworkLoaded and not titleSeenAt then titleSeenAt = elapsed end
            local artFade = assigned.title and smooth((elapsed - assigned.title) / 0.75) or 0
            setAlpha(logoAlpha, hasLogo and 1 - artFade or 1)
            setAlpha(shineAlpha, hasLogo and 1 - artFade * 0.40 or 1)
            shadow.Visible = hasLogo
            local crossFade = titleSeenAt and smooth((elapsed - titleSeenAt) / 0.32) or 0
            nativeTitle.Visible = crossFade < 1
            if nativeTitle.Visible then
                for _, layer in ipairs(nativeLayers) do
                    setAlpha(layer.alpha, 1 - (1 - layer.base) * (1 - crossFade) * entry)
                end
            end
            local reflection = reduced and -1.5 or (-1.45 + math.min(1, (elapsed % 7.5) / 3.2) * 2.9)
            shineGradient.Offset = V2(reflection, 0)
            nativeShineGradient.Offset = V2(reflection, 0)
            nativeGradient.Offset = V2(0, reduced and 0 or math.sin(elapsed * 0.35) * 0.035)

            local bgFade = assigned.background and smooth((elapsed - assigned.background) / 1.0) or 0
            setAlpha(backgroundAlpha, 1 - bgFade)
            local breathe = reduced and 0 or math.sin(elapsed * 0.24) * 0.0025
            background.Size = U2(1.025 + breathe, 1.025 + breathe)
            background.Position = U2(0.5 + (reduced and 0 or math.sin(elapsed * 0.17) * 0.002), 0.5)
            washGradient.Rotation = 24 + (reduced and 0 or math.sin(elapsed * 0.12) * 8)
            for _, fog in ipairs(fogs) do
                local i = fog.index
                fog.object.Position = U2(0.5 + (reduced and 0 or math.sin(elapsed * (0.055 + i * 0.012) + i) * 0.11),
                    0.42 + i * 0.105 + (reduced and 0 or math.sin(elapsed * 0.16 + i) * 0.012))
            end
            for _, glow in ipairs(candleGlows) do
                setAlpha(glow.alpha, reduced and 0.78 or (0.73 + math.sin(elapsed * 1.65 + glow.phase) * 0.032
                    + math.sin(elapsed * 4.2 + glow.phase) * 0.008))
            end
            for _, p in ipairs(particles) do
                local life = (elapsed / p.life + p.offset) % 1
                p.object.Position = UDim2.fromOffset(p.x + life * p.drift + math.sin(elapsed * 0.7 + p.offset * 6) * p.sway,
                    900 - life * 930)
                setAlpha(p.alpha, 1 - math.sin(life * math.pi) ^ 1.5 * p.opacity)
            end

            fill.Size = U2(current, 1)
            head.Position, halo.Position = U2(current, 0), U2(current, 0)
            head.Visible, halo.Visible = current > 0.002, current > 0.002
            local integer = current >= 1 and 100 or math.floor(current * 100)
            if integer ~= lastPercent then percent.Text = tostring(integer) .. "%"; lastPercent = integer end
            fireGradient.Offset = V2(reduced and 0 or math.sin(elapsed * 0.52) * 0.055, 0)
            fireTexture.Position = U2(0.5 + (reduced and 0 or math.sin(elapsed * 0.4) * 0.20), 0.5)
            barDetails.sheenGradient.Offset = V2(reduced and -1.5 or (-1.4 + math.min(1, (elapsed % 6.5) / 2.9) * 2.8), 0)
            barDetails.metal.Offset = V2(reduced and 0 or math.sin(elapsed * 0.22) * 0.12, 0)
            for _, p in ipairs(sparks) do
                local life = (elapsed / (p.speed * 1.3) + p.offset) % 1
                p.object.Position = UDim2.fromOffset(363 + current * 874 + life * p.drift,
                    527 - life * 52 + life * life * 20)
                setAlpha(p.alpha, current < 0.02 and 1 or (1 - math.sin(life * math.pi) * 0.76))
            end
            for i, rim in ipairs(rims) do
                rim.Offset = V2(reduced and 0 or math.sin(elapsed * 0.19 + i * 1.8) * 0.45, 0)
            end
            for i, glow in ipairs(optics.inward) do
                setAlpha(glow, 0.84 + (reduced and 0 or math.sin(elapsed * 0.6 + i * 1.3) * 0.035))
            end
            for i, reflected in ipairs(optics.reflections) do
                reflected.Offset = V2(reduced and -1.5 or (-1.6 + ((elapsed / (19 + i * 5) + i * 0.28) % 1) * 3.2), 0)
            end

            if state.prepareError and not completeTime then
                completeTime, state.ready = elapsed, true
                caption.Text, caption.TextColor3 = "Unable to load hub", RGB(255, 155, 126)
                hint.Text = mobile and "Tap to close" or "Click to close"
                warn("[HzReyzn] " .. state.prepareError)
            elseif current == 1 and not completeTime then
                completeTime, state.ready = elapsed, true
                caption.Text = "Loading completed"
                barStroke.Color = RGB(255, 187, 103)
                if Config.WaitForInput then
                    hint.Text = mobile and "Tap anywhere to continue" or "Click anywhere to continue"
                end
            end

            local pulse, phase = 0, 0
            if state.ready and not state.prepareError and completeTime then
                phase = (elapsed - completeTime) % math.max(1.5, Config.FlashInterval)
                if phase < 1 then pulse = math.min(1, phase / 0.12) * math.exp(-5.5 * math.max(0, phase - 0.12)) end
            end
            if reduced then pulse = pulse * 0.3 end
            for _, a in ipairs(flareEntries) do setAlpha(a, 1 - pulse * 0.9) end
            setAlpha(flareRingAlpha, 1 - pulse * 0.43)
            flareScale.Scale = 0.8 + math.min(1, phase) * 0.6
            setAlpha(flashAlpha, 1 - pulse * 0.032)
            setAlpha(reflectionAlpha, 1 - pulse * 0.65)
            setAlpha(barDetails.underglowAlpha, 0.94 - current * 0.04 - pulse * 0.04)
            reflectionGradient.Offset = V2(-1.3 + math.min(1, phase / 0.85) * 2.6, 0)
            setAlpha(hintAlpha, state.ready and (0.16 + (reduced and 0 or math.sin(elapsed * 1.5) * 0.055)) or 1)
            skip.Visible = Config.AllowSkip and not exitTime and not state.ready and elapsed >= Config.SkipAfter and state.prepared

            if state.ready and not exitTime then
                local auto = not Config.WaitForInput and completeTime and elapsed - completeTime >= Config.Hold
                if state.exitRequested or auto then exitTime = elapsed; skip.Visible = false end
            end
            if exitTime then
                local t = math.clamp((elapsed - exitTime) / fadeOut, 0, 1)
                local exitEase = TweenService:GetValue(t, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
                setFade(1 - exitEase)
                stage.Position = UDim2.new(0.5, 0, 0.5, reduced and 0 or exitEase * 20)
                if t >= 1 then cleanup(false) end
            else
                setFade(smooth(elapsed / 0.7))
            end
        end)

        -- Espera cooperativa. Al cerrarse o reiniciarse, se liberan las conexiones.
        while state.alive do task.wait(0.04) end
        return state.cancelled and "cancelled" or (state.prepareError and "failed" or "completed")
    end

    local ok, outcome = xpcall(run, debug.traceback)
    if not ok then
        warn("[HzReyzn] Error en la pantalla de carga: " .. tostring(outcome))
        cleanup(false)
    end
    if not ok then return "failed" end
    if state.cancelled or outcome == "failed" then return outcome end
    if type(Config.OnReady) == "function" then
        local callbackOK, err = xpcall(Config.OnReady, debug.traceback)
        if not callbackOK then warn("[HzReyzn] Error al abrir el hub: " .. tostring(err)) end
    end
    return outcome
end

-- PEGA AQUI EL CODIGO ACTUAL DE HzReyzn Hub, si no usas Config.OnReady.
-- La pantalla anterior termina y libera sus efectos antes de llegar aqui.
